toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #F6F4EE;
  font-family: "EB Garamond, serif";
}

>sumiInk = #1A1918;
>hankoRed = #B85D43;
>subtleGray = #7A756D;

circle #ensoRing {
  at: center of canvas;
  size: 260px;
  fill: none;
  stroke: >sumiInk;
  stroke-width: 14px;
}

rect #ensoBreak {
  at: center of canvas;
  size: 70px 180px;
  fill: #F6F4EE;
  rotation: 35deg;
}

rect #hankoStamp {
  at: right of #ensoRing offset 24px;
  size: 32px 32px;
  fill: >hankoRed;
  radius: 3px;
}

text #hankoGlyph {
  at: center of #hankoStamp;
  content: "静";
  font-size: 18px;
  color: #F6F4EE;
}

text #brandName {
  at: below #ensoRing offset 56px;
  content: "M A   T O K I";
  font-size: 24px;
  font-weight: 500;
  color: >sumiInk;
}

text #tagline {
  at: below #brandName offset 14px;
  content: "THE ART OF EMPTINESS";
  font-size: 11px;
  color: >subtleGray;
}
